<?php
declare(strict_types=1);

namespace Ports\Algorithms\Graphs;

use function Ports\Algorithms\Sorting\mergeSort;
function tarjanScc(array $graph): array { $n = count($graph); $index = array_fill(0,$n,-1); $low = array_fill(0,$n,0); $onStack = array_fill(0,$n,false); $stack = $components = []; $counter = 0; $connect = function(int $v) use (&$connect,&$index,&$low,&$onStack,&$stack,&$components,&$counter,$graph): void { $index[$v] = $low[$v] = $counter++; $stack[] = $v; $onStack[$v] = true; foreach ($graph[$v] as $neighbor) { if ($index[$neighbor] === -1) { $connect($neighbor); $low[$v] = min($low[$v],$low[$neighbor]); } elseif ($onStack[$neighbor]) $low[$v] = min($low[$v],$index[$neighbor]); } if ($low[$v] !== $index[$v]) return; $component = []; do { $member = array_pop($stack); $onStack[$member] = false; $component[] = $member; } while ($member !== $v); $components[] = mergeSort($component); }; foreach ($graph as $v => $_) if ($index[$v] === -1) $connect($v); return $components; }
function kosarajuScc(array $graph): array { $n = count($graph); $reversed = array_fill(0,$n,[]); foreach ($graph as $v => $neighbors) foreach ($neighbors as $neighbor) $reversed[$neighbor][] = $v; $visited = array_fill(0,$n,false); $finish = []; $fill = function(int $v) use (&$fill,&$visited,&$finish,$graph): void { $visited[$v] = true; foreach ($graph[$v] as $neighbor) if (!$visited[$neighbor]) $fill($neighbor); $finish[] = $v; }; $collect = function(int $v,array &$component) use (&$collect,&$visited,$reversed): void { $visited[$v] = true; $component[] = $v; foreach ($reversed[$v] as $neighbor) if (!$visited[$neighbor]) $collect($neighbor,$component); }; foreach ($graph as $v => $_) if (!$visited[$v]) $fill($v); $visited = array_fill(0,$n,false); $components = []; foreach (array_reverse($finish) as $v) { if ($visited[$v]) continue; $component = []; $collect($v,$component); $components[] = mergeSort($component); } return $components; }
